export function calculateFinalPriceA(item: Item) {
  const base = item.basePrice;
  const discount = Math.min(base * 0.1, item.maxDiscount || 0);
  const tax = base * 0.2;
  return base - discount + tax;
}

export function calculateFinalPriceB(product: Product) {
  const base = product.basePrice;
  const discount = Math.min(base * 0.1, product.maxDiscount || 0);
  const tax = base * 0.2;
  return base - discount + tax;
}

// Version A
export function calculateFinalPrice(item: { basePrice:number, maxDiscount?:number }) {
  const discount = Math.min(item.basePrice * 0.1, item.maxDiscount || 0);
  const tax = item.basePrice * 0.2;
  return item.basePrice - discount + tax;
}
export function handlerA(item:any){ return calculateFinalPrice(item); }
export function handlerB(product:any){ return calculateFinalPrice(product); }

// Version B
class BasePricer {
  protected compute(item:any) {
    const discount = Math.min(item.basePrice * 0.1, item.maxDiscount || 0);
    const tax = item.basePrice * 0.2;
    return item.basePrice - discount + tax;
  }
}
class OrderPricer extends BasePricer { public price(o:any){ return this.compute(o); } }
class CartPricer extends BasePricer { public price(c:any){ return this.compute(c); } }
